"use strict";Object.defineProperty(exports,"__esModule",{value:!0});const kyc_1=require("../kyc");describe("getEffectiveKycStatus",()=>{it("returns unverified for no applications",()=>{const e=(0,kyc_1.getEffectiveKycStatus)([]);expect(e.isVerified).toBe(!1);expect(e.level).toBe(0);expect(e.features).toEqual([]);expect(e.effectiveApplication).toBeNull()});it("returns unverified for only PENDING applications",()=>{const e=(0,kyc_1.getEffectiveKycStatus)([{status:"PENDING",level:{level:1,features:[]}}]);expect(e.isVerified).toBe(!1);expect(e.level).toBe(0)});it("returns Level 1 verified for single APPROVED Level 1",()=>{const e=(0,kyc_1.getEffectiveKycStatus)([{status:"APPROVED",level:{level:1,features:["feature1"]}}]);expect(e.isVerified).toBe(!0);expect(e.level).toBe(1);expect(e.features).toContain("feature1")});it("returns Level 1 when Level 1 APPROVED + Level 2 PENDING",()=>{const e=(0,kyc_1.getEffectiveKycStatus)([{status:"APPROVED",level:{level:1,features:["feature1"]}},{status:"PENDING",level:{level:2,features:["feature2"]}}]);expect(e.isVerified).toBe(!0);expect(e.level).toBe(1);expect(e.features).toEqual(["feature1"])});it("returns Level 2 with cumulative features when both approved",()=>{const e=(0,kyc_1.getEffectiveKycStatus)([{status:"APPROVED",level:{level:1,features:["feature1"]}},{status:"APPROVED",level:{level:2,features:["feature2"]}}]);expect(e.isVerified).toBe(!0);expect(e.level).toBe(2);expect(e.features).toContain("feature1");expect(e.features).toContain("feature2")});it("ignores REJECTED applications",()=>{const e=(0,kyc_1.getEffectiveKycStatus)([{status:"REJECTED",level:{level:1,features:[]}},{status:"APPROVED",level:{level:1,features:["feature1"]}}]);expect(e.isVerified).toBe(!0);expect(e.level).toBe(1)});it("handles malformed feature JSON gracefully",()=>{const e=(0,kyc_1.getEffectiveKycStatus)([{status:"APPROVED",level:{level:1,features:"invalid-json{"}}]);expect(e.isVerified).toBe(!0);expect(e.level).toBe(1);expect(e.features).toEqual([])});it("handles applications without level data",()=>{const e=(0,kyc_1.getEffectiveKycStatus)([{status:"APPROVED",level:null}]);expect(e.isVerified).toBe(!1)})});